--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: -
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


--
-- Name: generate_order_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_order_number() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  next_number INTEGER;
BEGIN
  SELECT COALESCE(MAX(CAST(SUBSTRING(order_number FROM '[0-9]+') AS INTEGER)), 1000) + 1
  INTO next_number
  FROM production_orders;
  
  NEW.order_number := next_number::VARCHAR;
  RETURN NEW;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
        id,
        user_id,
        email,
        role_profile,
        full_name,
        status
    )
    VALUES (
        NEW.id,
        NEW.id,  -- user_id = id do usuário
        NEW.email,
        'admin',
        COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email),
        'ativo'
    )
    ON CONFLICT (id) DO UPDATE
    SET 
        user_id = EXCLUDED.user_id,
        email = EXCLUDED.email,
        role_profile = 'admin';
    
    RETURN NEW;
END;
$$;


--
-- Name: refresh_production_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_production_stats() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  stats_id UUID;
  total_prod INTEGER;
  delayed_count INTEGER;
  stages_data JSONB;
BEGIN
  -- Buscar ou criar ID para estatísticas
  SELECT id INTO stats_id FROM production_stats LIMIT 1;
  IF stats_id IS NULL THEN
    stats_id := uuid_generate_v4();
  END IF;

  -- Calcular total em produção
  SELECT COUNT(*) INTO total_prod
  FROM production_orders
  WHERE status != 'Finalizado' AND status != 'Entregue';

  -- Calcular atrasados
  SELECT COUNT(*) INTO delayed_count
  FROM production_orders
  WHERE expected_delivery < NOW() 
    AND status != 'Finalizado' 
    AND status != 'Entregue';

  -- Construir JSON de estágios
  SELECT jsonb_object_agg(
    COALESCE(current_stage, 'Desconhecido'),
    total_count
  )
  INTO stages_data
  FROM (
    SELECT 
      current_stage,
      COUNT(*) as total_count
    FROM production_orders
    GROUP BY current_stage
  ) subquery;

  -- Se não houver dados, usar JSON vazio
  IF stages_data IS NULL THEN
    stages_data := '{}'::jsonb;
  END IF;

  -- Inserir ou atualizar estatísticas
    id, 
    total_in_production, 
    stages, 
    delayed, 
    updated_at
  )
  VALUES (
    stats_id, 
    COALESCE(total_prod, 0), 
    COALESCE(stages_data, '{}'::jsonb), 
    COALESCE(delayed_count, 0), 
    NOW()
  )
  ON CONFLICT (id) DO UPDATE SET
    total_in_production = EXCLUDED.total_in_production,
    stages = EXCLUDED.stages,
    delayed = EXCLUDED.delayed,
    updated_at = EXCLUDED.updated_at;
END;
$$;


--
-- Name: update_product_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_product_stock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Atualizar o estoque do produto
    UPDATE products 
    SET current_stock = NEW.quantidade_nova,
        updated_at = now()
    WHERE id = NEW.product_id;
    
    RETURN NEW;
END;
$$;


