-- Name: update_production_stats_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_production_stats_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM refresh_production_stats();
  RETURN NULL;
END;
$$;


